// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.stream.Collectors;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.QueryResults;
import org.eclipse.rdf4j.query.TupleQuery;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.sail.lmdb.LmdbStore;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * Differential tests for {@link NativeRowSeeder}: an external input binding whose value the store's
 * exact-representation {@code idOf} lookup cannot resolve must not silently turn the evaluation into zero rows. Two
 * wrong-results flavors: (1) on a legacy store (no canonical-language-tags property) a language tag is stored verbatim,
 * so a term-equal binding with a differently cased tag misses {@code idOf} even though the term is present and the
 * generic evaluator matches it; (2) a value genuinely absent from the store bound to a variable that appears in no
 * statement pattern (projection-only) constrains nothing, so the generic evaluator still returns rows carrying that
 * binding.
 */
public class LmdbNativeEntryBindingSeedTest {

	private static final String EX = "http://example.com/";
	private static final String NATIVE_FLAG = "rdf4j.lmdb.nativeQueryEngine.enabled";

	@TempDir
	File dataDir;

	private SailRepository repository;

	@BeforeEach
	public void setUp() {
		// Create the store once so its properties file exists, then strip the canonical-language-tags marker to
		// simulate a legacy store: such stores write language tags verbatim, which is what makes a term-equal
		// binding with a different tag spelling miss the exact-representation id lookup.
		openRepository();
		repository.shutDown();
		stripCanonicalLanguageTags();
		openRepository();
		try (SailRepositoryConnection conn = repository.getConnection()) {
			ValueFactory vf = conn.getValueFactory();
			IRI s1 = vf.createIRI(EX, "s1");
			IRI s2 = vf.createIRI(EX, "s2");
			conn.add(s1, vf.createIRI(EX, "p"), vf.createLiteral("hello", "en"));
			conn.add(s2, vf.createIRI(EX, "q"), vf.createLiteral("plain"));
		}
		// Reopen so the ValueStore's Value-keyed id cache is cold: that cache compares by Value.equals (language
		// tags case-insensitive) and would mask the byte-exact disk lookup this test targets.
		repository.shutDown();
		openRepository();
	}

	@AfterEach
	public void tearDown() {
		if (repository != null) {
			repository.shutDown();
		}
	}

	/**
	 * Language tags compare case-insensitively ({@code "hello"@EN} and {@code "hello"@en} are the same RDF term), so
	 * the generic evaluator matches the stored statement. The native seeder's exact id lookup misses the verbatim
	 * {@code @en} spelling and currently aborts the whole evaluation with zero rows.
	 */
	@Test
	public void caseDifferentLanguageTagBindingMatchesGenericEvaluator() {
		String query = "SELECT ?s WHERE { ?s <" + EX + "p> ?o }";
		Value bound = repository.getValueFactory().createLiteral("hello", "EN");

		// KNOWN STORE-LEVEL LIMITATION, pinned as parity: on a legacy store (verbatim language tags) the byte-exact
		// ValueStore.getId lookup misses the case-different spelling for BOTH engines — the generic arm over LMDB
		// returns empty too, so this is not a native-engine divergence. SPARQL semantics (and the MemoryStore) would
		// match; fixing that is a store-level work item outside this milestone. This test guards native/generic
		// parity so the native engine never diverges from its in-store oracle on this class.
		assertThat(rows(query, "o", bound))
				.as("native rows must match the generic evaluator for a case-different language-tag binding")
				.isEqualTo(genericRows(query, "o", bound));
	}

	/**
	 * A store-absent value bound to a variable that IS a native slot (a BIND source) must not abort the evaluation: the
	 * generic evaluator computes {@code BIND(?x AS ?y)} from the input binding and returns the row.
	 */
	@Test
	public void storeAbsentBindingOnBindSourceKeepsRows() {
		String query = "SELECT ?s ?y WHERE { ?s <" + EX + "q> ?o . BIND(?x AS ?y) }";
		Value bound = repository.getValueFactory().createLiteral("zzz-absent-from-store");

		List<String> generic = genericRows(query, "x", bound);
		assertThat(generic)
				.as("generic evaluator: ?y copies the input binding and the row survives")
				.containsExactly("s=" + EX + "s2|y=\"zzz-absent-from-store\"");
		assertThat(rows(query, "x", bound))
				.as("native rows must match the generic evaluator for a store-absent BIND-source binding")
				.isEqualTo(generic);
	}

	/**
	 * A store-absent value bound to a projection-only variable constrains no statement pattern; the generic evaluator
	 * returns the pattern's rows with the input binding carried through. The native seeder currently treats the
	 * unresolvable id as "no rows possible".
	 */
	@Test
	public void storeAbsentBindingOnProjectionOnlyVariableKeepsRows() {
		String query = "SELECT ?s ?x WHERE { ?s <" + EX + "q> ?o }";
		Value bound = repository.getValueFactory().createLiteral("zzz-absent-from-store");

		List<String> generic = genericRows(query, "x", bound);
		assertThat(generic)
				.as("generic evaluator: the pattern still matches (the root projection drops the unmatched input"
						+ " binding, but the row survives)")
				.containsExactly("s=" + EX + "s2");
		assertThat(rows(query, "x", bound))
				.as("native rows must match the generic evaluator for a store-absent projection-only binding")
				.isEqualTo(generic);
	}

	/**
	 * The input binding is visible to the WHERE clause even when its value is absent from the store: the generic
	 * evaluator evaluates {@code FILTER(?x != ?o)} with {@code ?x} bound and keeps the row. The native engine must not
	 * turn the unresolvable id into an empty result.
	 */
	@Test
	public void storeAbsentBindingVisibleToFilterKeepsRows() {
		String query = "SELECT ?s WHERE { ?s <" + EX + "q> ?o . FILTER(?x != ?o) }";
		Value bound = repository.getValueFactory().createLiteral("zzz-absent-from-store");

		List<String> generic = genericRows(query, "x", bound);
		assertThat(generic)
				.as("generic evaluator: ?x is bound and differs from \"plain\", the row survives")
				.containsExactly("s=" + EX + "s2");
		assertThat(rows(query, "x", bound))
				.as("native rows must match the generic evaluator for a store-absent filter binding")
				.isEqualTo(generic);
	}

	private void openRepository() {
		repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc")));
		repository.init();
	}

	private void stripCanonicalLanguageTags() {
		Path properties = dataDir.toPath().resolve("store.properties");
		try {
			List<String> kept = Files.readAllLines(properties)
					.stream()
					.filter(line -> !line.startsWith("canonical-language-tags"))
					.collect(Collectors.toList());
			Files.write(properties, kept);
		} catch (IOException e) {
			throw new UncheckedIOException("Unable to rewrite " + properties, e);
		}
	}

	private List<String> rows(String query, String bindingName, Value bindingValue) {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			TupleQuery tupleQuery = conn.prepareTupleQuery(query);
			tupleQuery.setBinding(bindingName, bindingValue);
			return QueryResults.asList(tupleQuery.evaluate())
					.stream()
					.map(LmdbNativeEntryBindingSeedTest::render)
					.collect(Collectors.toList());
		}
	}

	private List<String> genericRows(String query, String bindingName, Value bindingValue) {
		String previous = System.getProperty(NATIVE_FLAG);
		try {
			System.setProperty(NATIVE_FLAG, "false");
			return rows(query, bindingName, bindingValue);
		} finally {
			if (previous == null) {
				System.clearProperty(NATIVE_FLAG);
			} else {
				System.setProperty(NATIVE_FLAG, previous);
			}
		}
	}

	private static String render(BindingSet bindings) {
		return bindings.getBindingNames()
				.stream()
				.sorted()
				.map(name -> name + "=" + bindings.getValue(name))
				.collect(Collectors.joining("|"));
	}
}
